    "lyrics": "就散席了 人客急将美酒喝掉赶於舞曲奏尽前离坐是我夜了吧 最後这分钟到场待热情尽过 方看到场内灿烂灯火好想唱一阙歌 叫你认清楚我我也曾到来庆贺好想唱一阙歌 见证日子怎过哪个时势能没有歌若问你会如何 你会骂我别傻剩下光景不多但是你会如何 我也没有奈何盼你亦赏面安坐 替我用掌声和唱著这歌就散席了 人客心知个中奥妙将讲到一半话题完掉若注定这样 故事尾声方进场别人话迟极了 愿时代仍为我留了座只想唱一阙歌 叫你认清楚我我也曾到来庆贺只想唱一阙歌 一首凄美的赞歌派对完结前为你写的歌若问你会如何 你会骂我别傻剩下光景不多但是你会如何 我也没有奈何盼你耐心的安坐怕以後掌声未够是晚多若问哪里不妥 你会骂我别傻剩下光景不多 别寄望太多日後我会如何 我也没有奈何却怕在今晚之後 不知有谁来迫我转唱另一些歌"
